INSERT INTO sg_categories (slug, name_th, name_en, vibe, target_recipient, guardrail, core_signatures) VALUES
  ('eco-friendly', 'ชุดผลิตภัณฑ์รักษ์โลกและสิ่งแวดล้อม (Eco-Friendly Series)', 'Eco-Friendly & Sustainability (Green & Earth)', 'ยั่งยืน รักษ์โลก เป็นมิตรต่อธรรมชาติ', 'องค์กรสาย ESG, แคมเปญเพื่อสิ่งแวดล้อม', 'เน้นใช้วัสดุรีไซเคิล ย่อยสลายได้ หรือลดขยะพลาสติก', '["กระบอกน้ำฟางข้าวพกพา","สมุดปกกระดาษรีไซเคิล","กระเป๋าผ้าแคนวาสออร์แกนิก","ชุดช้อนส้อมพกพาวัสดุชีวภาพ"]'),
  ('classic-oriental', 'ชุดศิลปะร่วมสมัยและตะวันออก (Classic Oriental)', 'Classic Oriental (Mindfulness & Craft)', 'ประณีต ทรงคุณค่า คลาสสิก', 'ผู้ใหญ่, แขก VIP ต่างชาติ', 'ตรวจเช็คความหมายมงคลของลวดลาย', '["สมุดคลิปโลหะ/ปกหนัง","ปากกาไม้หัวทองเหลือง","แฟลชไดร์ฟหยูอี้","ชุดถ้วยชาเซรามิก"]'),
  ('novelty-self-care', 'ชุด Novelty & Self-Care', 'Novelty & Self-Care (Warm & Wellness)', 'ผ่อนคลาย อบอุ่น ใส่ใจ', 'กลุ่มผู้หญิง, พนักงานสาย Wellness', 'ห้ามเคลมสรรพคุณ Medical โดยไม่มีหลักฐาน', '["เทียนหอมอโรมา","แก้วน้ำอเนกประสงค์","ตุ๊กตาผ้าขนหนู","สบู่ธรรมชาติกลิ่นกุหลาบ"]'),
  ('executive-smart-tech', 'ชุดนวัตกรรมทางการทำงานอัจฉริยะ (Executive Smart Tech)', 'Executive Smart Tech (Modern & Work)', 'ทันสมัย นวัตกรรม เป็นมืออาชีพ', 'ผู้บริหาร, กลุ่มนักธุรกิจยุคใหม่', 'ตรวจสเปกแบตเตอรี่และการรับรองความปลอดภัย', '["Smart Powerbank Notebook","Power Bank 10000mAh","ปากกาโลหะหมึกเจล","แฟลชไดร์ฟสายรัดแม่เหล็ก"]');
