INSERT INTO sg_sub_catalogs (code, name, description) VALUES
  ('canonical_catalog', 'Canonical Product Catalog (Single SKUs & Verified Offers)', 'สินค้าและเซ็ตเสนอขายที่มี PID และรหัส FlowAccount สมบูรณ์ พร้อมออกใบเสนอราคาอัตโนมัติ'),
